BEGIN;
CREATE TABLE IF NOT EXISTS permissions (key TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role TEXT NOT NULL, permission_key TEXT NOT NULL REFERENCES permissions(key) ON DELETE CASCADE, PRIMARY KEY(role,permission_key));
CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_org_idx ON projects(organization_id);
CREATE TABLE IF NOT EXISTS project_members (project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin','owner')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(project_id,user_id));
CREATE INDEX IF NOT EXISTS project_members_user_idx ON project_members(user_id);
CREATE TABLE IF NOT EXISTS billing_customers (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, revenuecat_app_user_id TEXT NOT NULL UNIQUE, environment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_idempotency (provider TEXT NOT NULL,event_id TEXT NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'received',PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS api_keys (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,key_prefix TEXT NOT NULL,key_hash BYTEA NOT NULL UNIQUE,expires_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS api_keys_user_idx ON api_keys(user_id);
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE SET NULL,organization_id UUID REFERENCES organizations(id) ON DELETE SET NULL,action TEXT NOT NULL,resource_type TEXT,resource_id TEXT,request_id TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_user_time_idx ON audit_logs(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS data_observations_project_idx ON data_observations(project_id,observed_at DESC);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='data_observations_project_fk') THEN ALTER TABLE data_observations ADD CONSTRAINT data_observations_project_fk FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL; END IF; IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='agent_runs_project_fk') THEN ALTER TABLE agent_runs ADD CONSTRAINT agent_runs_project_fk FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL; END IF; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS agent_runs_run_key_uq ON agent_runs(run_id) WHERE run_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS agent_checkpoints(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),agent_run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,checkpoint_key TEXT NOT NULL,state JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(agent_run_id,checkpoint_key));
INSERT INTO permissions(key,description) VALUES('project:read','Read project data'),('project:write','Modify project data'),('project:admin','Manage project membership'),('billing:read','Read billing state'),('billing:manage','Manage billing'),('mcp:use','Use MCP tools'),('mcp:admin','Manage MCP OAuth clients'),('audit:read','Read audit logs') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role,permission_key) SELECT r.role,p.key FROM(VALUES('member'),('admin'),('owner'))r(role) CROSS JOIN permissions p WHERE(r.role='member' AND p.key IN('project:read','billing:read','mcp:use')) OR(r.role='admin' AND p.key IN('project:read','project:write','project:admin','billing:read','mcp:use','audit:read')) OR r.role='owner' ON CONFLICT DO NOTHING;
INSERT INTO schema_migrations(version) VALUES('002_owned_platform_core') ON CONFLICT DO NOTHING;
COMMIT;
